#include "cp437.h"
typedef uint8_t u8; typedef uint16_t u16; typedef uint32_t u32; typedef uint64_t u64;
#define EOC 0x0FFFFFF8u
#define R16(p,o) ((u32)(p)[o]|(u32)(p)[(o)+1]<<8)
#define R32(p,o) (R16(p,o)|R16(p,(o)+2)<<16)
static void W16(u8*p,int o,u32 v){ p[o]=(u8)v; p[o+1]=(u8)(v>>8); }
static void W32(u8*p,int o,u32 v){ W16(p,o,v&0xFFFF); W16(p,o+2,v>>16); }
static u16 cp2u(u8 c){ if(c<0x80)return c; for(unsigned i=0;i<sizeof cp437_map/sizeof cp437_map[0];i++) if(cp437_map[i].c==c)return cp437_map[i].u; return '_'; }
static u8 u2cp(u32 u){ if(u>=32&&u<127)return (u8)u; for(unsigned i=0;i<sizeof cp437_map/sizeof cp437_map[0];i++) if(cp437_map[i].u==u)return cp437_map[i].c; return '_'; }
static int rs(fatvol*v,u32 s,void*b){ return s<v->d.sectors&&!v->d.rd(v->d.start+s,b)?0:VE_IO; }
static int ws(fatvol*v,u32 s,const void*b){ return s<v->d.sectors&&!v->d.wr(v->d.start+s,b)?0:VE_IO; }
static u32 c2s(fatvol*v,u32 c){ return v->datasec+(c-2)*v->spc; }
static int cvalid(fatvol*v,u32 c){ return c>=2&&c<v->clusters+2; }
static int fsec(fatvol*v,u32 s){ if(v->cs==s)return 0; int r=rs(v,s,v->buf); v->cs=r?0xFFFFFFFFu:s; return r; }
static u32 get(fatvol*v,u32 c){ if(!cvalid(v,c))return 0x0FFFFFFFu; if(fsec(v,v->rsvd+c/128))return 0x0FFFFFFFu; return R32(v->buf,(c%128)*4)&0x0FFFFFFFu; }
static int put(fatvol*v,u32 c,u32 val){ if(!cvalid(v,c))return VE_IO; if(!v->fsdirty&&v->fsinfo){ static u8 t[512]; if(!rs(v,v->fsinfo,t)&&R32(t,0)==0x41615252u){ W32(t,488,0xFFFFFFFFu); W32(t,492,0xFFFFFFFFu); ws(v,v->fsinfo,t); } v->fsdirty=1; } if(fsec(v,v->rsvd+c/128))return VE_IO; u32 o=(c%128)*4; W32(v->buf,o,(R32(v->buf,o)&0xF0000000u)|(val&0x0FFFFFFFu)); for(u32 f=0;f<v->nfat;f++) if(ws(v,v->rsvd+f*v->fatsz+c/128,v->buf))return VE_IO; return 0; }
static u32 calloc_(fatvol*v){ for(u32 n=0;n<v->clusters;n++){ u32 c=2+(v->hint-2+n)%v->clusters; if(get(v,c)==0){ if(put(v,c,0x0FFFFFFFu))return 0; v->hint=c+1<v->clusters+2?c+1:2; return c; } } return 0; }
static void cfree(fatvol*v,u32 c){ for(u32 g=0;cvalid(v,c)&&g<=v->clusters;g++){ u32 n=get(v,c); put(v,c,0); c=n; } }
static int czero(fatvol*v,u32 c){ static u8 z[512]; memset(z,0,512); u32 s=c2s(v,c); for(u32 i=0;i<v->spc;i++) if(ws(v,s+i,z))return VE_IO; return 0; }
int fat_mount(fatvol*v,const vfs_dev*d){ memset(v,0,sizeof*v); v->d=*d; v->cs=0xFFFFFFFFu; static u8 b[512]; if(d->rd(d->start,b))return VE_IO; if(b[510]!=0x55||b[511]!=0xAA)return VE_FORMAT; u32 bps=R16(b,11),spc=b[13],rs_=R16(b,14),nf=b[16],rd=R16(b,17),t16=R16(b,19),fz16=R16(b,22),tot=R32(b,32),fz=R32(b,36),root=R32(b,44),fi=R16(b,48); if(bps!=512||!spc||(spc&(spc-1))||!rs_||!nf||nf>2||rd||t16||fz16||!fz||!tot)return VE_FORMAT; if(tot>d->sectors)tot=(u32)(d->sectors>0xFFFFFFFFu?0xFFFFFFFFu:d->sectors); u64 meta=(u64)rs_+(u64)nf*fz; if(meta>=tot)return VE_FORMAT; u32 cl=(tot-(u32)meta)/spc; if(cl<16)return VE_FORMAT; if((u64)cl+2>(u64)fz*128)cl=fz*128-2; v->spc=spc;v->rsvd=rs_;v->nfat=nf;v->fatsz=fz;v->datasec=(u32)meta;v->clusters=cl;v->root=root;v->fsinfo=fi>0&&fi<rs_?fi:0;v->hint=2; if(!cvalid(v,root))return VE_FORMAT; v->ok=1; return 0; }
/* Ordner-Iterator: liefert Eintraege samt langem Namen */
typedef struct { u8 e[32]; u32 sec; int off; u32 lsec[21]; int loff[21]; int ln; char name[VFS_NAME+1]; } dent;
typedef int(*dcb)(fatvol*,dent*,void*);
static u8 sum83(const u8*n){ u8 s=0; for(int i=0;i<11;i++)s=(u8)(((s&1)<<7)+(s>>1)+n[i]); return s; }
static void sfname(const u8*e,char*o){ int k=0; for(int i=0;i<8&&e[i]!=' ';i++){ u8 c=e[i]; if(i==0&&c==5)c=0xE5; o[k++]=(c>='A'&&c<='Z'&&(e[12]&8))?c+32:c; } if(e[8]!=' '){ o[k++]='.'; for(int i=8;i<11&&e[i]!=' ';i++){ u8 c=e[i]; o[k++]=(c>='A'&&c<='Z'&&(e[12]&16))?c+32:c; } } o[k]=0; }
static int walk(fatvol*v,u32 dir,dcb cb,void*arg){ dent d; u16 lb[260]; int have=0; u8 lsum=0; d.ln=0; memset(lb,0,sizeof lb); static u8 sb[512]; u32 c=dir; for(u32 g=0;cvalid(v,c)&&g<=v->clusters;g++){ u32 s0=c2s(v,c); for(u32 i=0;i<v->spc;i++){ if(rs(v,s0+i,sb))return VE_IO; for(int o=0;o<512;o+=32){ u8*e=sb+o; if(e[0]==0)return 0; if(e[0]==0xE5){ have=0; d.ln=0; continue; } if((e[11]&0x3F)==0x0F){ int seq=e[0]&0x1F; if(e[0]&0x40){ memset(lb,0,sizeof lb); have=seq; lsum=e[13]; d.ln=0; } if(!seq||seq>20||!have||e[13]!=lsum){ have=0; d.ln=0; continue; } int base=(seq-1)*13; static const u8 pos[13]={1,3,5,7,9,14,16,18,20,22,24,28,30}; for(int k=0;k<13;k++) lb[base+k]=(u16)R16(e,pos[k]); if(d.ln<21){ d.lsec[d.ln]=s0+i; d.loff[d.ln]=o; d.ln++; } continue; } if(e[11]&8){ have=0; d.ln=0; continue; } memcpy(d.e,e,32); d.sec=s0+i; d.off=o; if(have&&lsum==sum83(e)){ int k=0; for(;k<VFS_NAME&&k<260&&lb[k]&&lb[k]!=0xFFFF;k++)d.name[k]=(char)u2cp(lb[k]); d.name[k]=0; } else { sfname(e,d.name); d.ln=0; } static u8 sv[512]; memcpy(sv,sb,512); int r=cb(v,&d,arg); if(r)return r; memcpy(sb,sv,512); have=0; d.ln=0; } } c=get(v,c); if(c>=EOC)return 0; } return 0; }
static int lc(int c){ if(c>='A'&&c<='Z')return c+32; if(c==0x8E)return 0x84; if(c==0x99)return 0x94; if(c==0x9A)return 0x81; return c; }
static int ieq(const char*a,const char*b,int n){ for(int i=0;i<n;i++) if(lc((u8)a[i])!=lc((u8)b[i])||!a[i])return 0; return !a[n]; }
typedef struct { const char*n; int l; dent r; int hit; } fnd;
static int fcb(fatvol*v,dent*d,void*a){ fnd*f=a; if(ieq(d->name,f->n,f->l)){ f->r=*d; f->hit=1; return 1; } return 0; }
static u32 ecl(const u8*e){ return R16(e,20)<<16|R16(e,26); }
static int lookup(fatvol*v,const char*p,dent*o,u32*parent,int*isroot){ u32 cur=v->root; const char*s=p; int any=0; while(*s=='/')s++; *parent=v->root; if(isroot)*isroot=0; if(!*s){ if(isroot)*isroot=1; return 0; } fnd f; while(*s){ const char*e=s; while(*e&&*e!='/')e++; f.n=s;f.l=(int)(e-s);f.hit=0; int r=walk(v,cur,fcb,&f); if(r<0)return r; if(!f.hit)return VE_NOENT; *parent=cur; *o=f.r; any=1; s=e; while(*s=='/')s++; if(*s){ if(!(o->e[11]&0x10))return VE_NOTDIR; cur=ecl(o->e); if(!cur)cur=v->root; if(!cvalid(v,cur))return VE_IO; } } return any?0:VE_NOENT; }
int fat_stat(fatvol*v,const char*p,vfs_ent*e){ dent d; u32 par; int root; int r=lookup(v,p,&d,&par,&root); if(r)return r; if(root){ if(e){ e->dir=1;e->size=0;e->mtime=0;e->name[0]=0; } return 0; } if(e){ e->dir=!!(d.e[11]&0x10); e->size=e->dir?0:R32(d.e,28); e->mtime=0; memcpy(e->name,d.name,VFS_NAME+1); } return 0; }
int64_t fat_read(fatvol*v,const char*p,void*b,u64 max){ dent d; u32 par; int root; int r=lookup(v,p,&d,&par,&root); if(r)return r; if(root||(d.e[11]&0x10))return VE_ISDIR; u64 sz=R32(d.e,28); if(sz>max)sz=max; u32 c=ecl(d.e); u64 o=0; static u8 s[512]; for(u32 g=0;o<sz;g++){ if(!cvalid(v,c)||g>v->clusters)return VE_IO; u32 s0=c2s(v,c); for(u32 i=0;i<v->spc&&o<sz;i++){ if(rs(v,s0+i,s))return VE_IO; u64 n=sz-o>512?512:sz-o; memcpy((u8*)b+o,s,n); o+=n; } c=get(v,c); } return (int64_t)sz; }
typedef struct { int(*cb)(const vfs_ent*,void*); void*a; } lst;
static int lcb(fatvol*v,dent*d,void*x){ lst*l=x; if(d->e[11]&8)return 0; if(!strcmp(d->name,".")||!strcmp(d->name,".."))return 0; static vfs_ent e; memcpy(e.name,d->name,VFS_NAME+1); e.dir=!!(d->e[11]&0x10); e.size=e.dir?0:R32(d->e,28); e.mtime=0; return l->cb(&e,l->a)?1:0; }
int fat_list(fatvol*v,const char*p,int(*cb)(const vfs_ent*,void*),void*a){ dent d; u32 par; int root; int r=lookup(v,p,&d,&par,&root); if(r)return r; u32 c=v->root; if(!root){ if(!(d.e[11]&0x10))return VE_NOTDIR; c=ecl(d.e); if(!c)c=v->root; } lst l={cb,a}; r=walk(v,c,lcb,&l); return r<0?r:0; }
static void dostime(u32 t,u8*e,int to,int dof){ u32 d=t/86400,r=t%86400,z=d+719468,era=z/146097,doe=z-era*146097,yoe=(doe-doe/1460+doe/36524-doe/146096)/365,doy=doe-(365*yoe+yoe/4-yoe/100),mp=(5*doy+2)/153,dd=doy-(153*mp+2)/5+1,m=mp<10?mp+3:mp-9,y=yoe+era*400+(m<=2); u32 yy=y>=1980?y-1980:0; W16(e,dof,(yy<<9)|(m<<5)|dd); W16(e,to,((r/3600)<<11)|(((r/60)%60)<<5)|((r%60)/2)); }
static int legal(const char*n,int l){ if(l<=0||l>250)return 0; if(n[l-1]=='.'||n[l-1]==' ')return 0; for(int i=0;i<l;i++){ u8 c=n[i]; if(c<32||c=='"'||c=='*'||c=='/'||c==':'||c=='<'||c=='>'||c=='?'||c=='\\'||c=='|')return 0; } return 1; }
typedef struct { int k; const u8*sn; int dup; } sn_t;
static int sncb(fatvol*v,dent*d,void*a){ sn_t*s=a; if(!memcmp(d->e,s->sn,11)){ s->dup=1; return 1; } return 0; }
static int mksn(fatvol*v,u32 dir,const char*n,int l,u8*o,int*lfn){ memset(o,' ',11); int dot=-1; for(int i=0;i<l;i++) if(n[i]=='.')dot=i; int k=0,plain=1,be=dot>0?dot:l; for(int i=0;i<be;i++){ u8 c=n[i]; if(c>='a'&&c<='z'){ plain=0; c-=32; } if(c==' '||c=='.'||c=='+'||c==','||c==';'||c=='='||c=='['||c==']'||c>=0x80){ plain=0; if(c==' '||c=='.')continue; c='_'; } if(k<8)o[k++]=c; else plain=0; } if(!k)o[k++]='_',plain=0; if(dot>0){ int x=0; for(int i=dot+1;i<l;i++){ u8 c=n[i]; if(c>='a'&&c<='z'){ plain=0; c-=32; } if(c==' '||c>=0x80||c=='+'||c==','||c==';'||c=='='||c=='['||c==']'){ plain=0; c='_'; } if(x<3)o[8+x++]=c; else plain=0; } } else if(dot==0)plain=0; if(be>8)plain=0; *lfn=!plain; sn_t s={0,o,0}; if(plain){ int r=walk(v,dir,sncb,&s); if(r<0)return r; if(!s.dup)return 0; *lfn=1; } for(int t=1;t<100000;t++){ char num[8]; int c=0,x=t; do{ num[c++]='0'+x%10; x/=10; }while(x); int bl=k; if(bl>7-c)bl=7-c; o[bl]='~'; for(int i=0;i<c;i++)o[bl+1+i]=num[c-1-i]; for(int i=bl+1+c;i<8;i++)o[i]=' '; s.dup=0; int r=walk(v,dir,sncb,&s); if(r<0)return r; if(!s.dup)return 0; } return VE_EXIST; }
/* Sucht n freie aufeinanderfolgende Plaetze, verlaengert den Ordner bei Bedarf */
static int slots(fatvol*v,u32 dir,int n,u32*ss,int*so){ static u8 b[512]; int run=0; u32 c=dir,last=dir; for(u32 g=0;cvalid(v,c)&&g<=v->clusters;g++){ u32 s0=c2s(v,c); last=c; for(u32 i=0;i<v->spc;i++){ if(rs(v,s0+i,b))return VE_IO; for(int o=0;o<512;o+=32){ if(b[o]==0xE5||b[o]==0){ if(run<n){ ss[run]=s0+i; so[run]=o; } run++; if(b[o]==0&&run<n){ /* Rest des Ordners ist frei */ } if(run>=n)return 0; } else run=0; } } c=get(v,c); if(c>=EOC)break; }
  u32 nc=calloc_(v); if(!nc)return VE_NOSPC; if(czero(v,nc)||put(v,last,nc))return VE_IO; u32 s0=c2s(v,nc); int need=n-run,idx=run; for(u32 i=0;i<v->spc&&need>0;i++) for(int o=0;o<512&&need>0;o+=32){ ss[idx]=s0+i; so[idx]=o; idx++; need--; } return need>0?VE_NOSPC:0; }
static int put_ent(fatvol*v,u32 s,int o,const u8*e){ static u8 b[512]; if(rs(v,s,b))return VE_IO; memcpy(b+o,e,32); return ws(v,s,b); }
static int add(fatvol*v,u32 dir,const char*n,int l,u8 attr,u32 clus,u32 size,u32 now,const u8*tmpl){ u8 sn[11]; int lfn; int r=mksn(v,dir,n,l,sn,&lfn); if(r)return r; int cnt=lfn?(l+12)/13:0; u32 ss[22]; int so[22]; r=slots(v,dir,cnt+1,ss,so); if(r)return r; u8 e[32]; if(tmpl)memcpy(e,tmpl,32); else { memset(e,0,32); dostime(now,e,14,16); memcpy(e+18,e+16,2); dostime(now,e,22,24); } memcpy(e,sn,11); e[11]=attr; e[12]=0; W16(e,20,clus>>16); W16(e,26,clus&0xFFFF); W32(e,28,size); if(e[0]==0xE5)e[0]=5; u8 ck=sum83(e); static const u8 pos[13]={1,3,5,7,9,14,16,18,20,22,24,28,30}; for(int i=0;i<cnt;i++){ int seq=cnt-i; u8 x[32]; memset(x,0,32); x[0]=(u8)(seq|(i==0?0x40:0)); x[11]=0x0F; x[13]=ck; int base=(seq-1)*13; for(int k=0;k<13;k++){ int q=base+k; u16 u=q<l?cp2u((u8)n[q]):q==l?0:0xFFFF; W16(x,pos[k],u); } if(put_ent(v,ss[i],so[i],x))return VE_IO; } if(put_ent(v,ss[cnt],so[cnt],e))return VE_IO; v->d.fl(); return 0; }
static int del_ent(fatvol*v,dent*d){ static u8 b[512]; for(int i=0;i<d->ln;i++){ if(rs(v,d->lsec[i],b))return VE_IO; b[d->loff[i]]=0xE5; if(ws(v,d->lsec[i],b))return VE_IO; } if(rs(v,d->sec,b))return VE_IO; b[d->off]=0xE5; return ws(v,d->sec,b); }
static int spl(fatvol*v,const char*p,u32*dir,const char**n,int*l){ size_t L=strlen(p); while(L>1&&p[L-1]=='/')L--; const char*e=p+L,*s=e; while(s>p&&s[-1]!='/')s--; int nl=(int)(e-s); if(nl<=0||!legal(s,nl)||(nl==1&&s[0]=='.')||(nl==2&&s[0]=='.'&&s[1]=='.'))return VE_INVAL; *n=s;*l=nl; static char par[VFS_PATH]; size_t pl=s-p; if(pl>=VFS_PATH)return VE_INVAL; memcpy(par,p,pl); par[pl]=0; dent d; u32 pp; int root; int r=lookup(v,par,&d,&pp,&root); if(r)return r; if(root){ *dir=v->root; return 0; } if(!(d.e[11]&0x10))return VE_NOTDIR; *dir=ecl(d.e); if(!*dir)*dir=v->root; return cvalid(v,*dir)?0:VE_IO; }
int fat_write(fatvol*v,const char*p,const void*b,u64 len,u32 now){ if(len>0xFFFFFFFFull)return VE_NOSPC; u32 dir; const char*n; int l; int r=spl(v,p,&dir,&n,&l); if(r)return r; char nm[VFS_NAME+1]; memcpy(nm,n,l); nm[l]=0; fnd f; f.n=nm;f.l=l;f.hit=0; r=walk(v,dir,fcb,&f); if(r<0)return r; if(f.hit&&(f.r.e[11]&0x10))return VE_ISDIR; if(f.hit&&(f.r.e[11]&1))return VE_DENIED;
  u32 first=0,prev=0; u64 o=0; u64 cb=(u64)v->spc*512; static u8 s[512]; while(o<len){ u32 c=calloc_(v); if(!c){ if(first)cfree(v,first); return VE_NOSPC; } if(prev){ if(put(v,prev,c)){ cfree(v,first); return VE_IO; } } else first=c; prev=c; u32 s0=c2s(v,c); for(u32 i=0;i<v->spc&&o<len;i++){ u64 k=len-o>512?512:len-o; memset(s,0,512); memcpy(s,(const u8*)b+o,k); if(ws(v,s0+i,s)){ cfree(v,first); return VE_IO; } o+=k; } } (void)cb; v->d.fl();
  if(f.hit){ u32 old=ecl(f.r.e); static u8 t[512]; if(rs(v,f.r.sec,t)){ if(first)cfree(v,first); return VE_IO; } u8*e=t+f.r.off; W16(e,20,first>>16); W16(e,26,first&0xFFFF); W32(e,28,(u32)len); dostime(now,e,22,24); e[11]|=0x20; if(ws(v,f.r.sec,t)){ if(first)cfree(v,first); return VE_IO; } v->d.fl(); if(old)cfree(v,old); return 0; }
  r=add(v,dir,nm,l,0x20,first,(u32)len,now,0); if(r&&first)cfree(v,first); return r; }
int fat_mkdir(fatvol*v,const char*p,u32 now){ u32 dir; const char*n; int l; int r=spl(v,p,&dir,&n,&l); if(r)return r; char nm[VFS_NAME+1]; memcpy(nm,n,l); nm[l]=0; fnd f; f.n=nm;f.l=l;f.hit=0; r=walk(v,dir,fcb,&f); if(r<0)return r; if(f.hit)return VE_EXIST; u32 c=calloc_(v); if(!c)return VE_NOSPC; if(czero(v,c)){ cfree(v,c); return VE_IO; } static u8 s[512]; memset(s,0,512); memset(s,' ',11); s[0]='.'; s[11]=0x10; dostime(now,s,22,24); W16(s,20,c>>16); W16(s,26,c&0xFFFF); memset(s+32,' ',11); s[32]='.';s[33]='.'; s[43]=0x10; u32 pc=dir==v->root?0:dir; W16(s+32,20,pc>>16); W16(s+32,26,pc&0xFFFF); if(ws(v,c2s(v,c),s)){ cfree(v,c); return VE_IO; } r=add(v,dir,nm,l,0x10,c,0,now,0); if(r)cfree(v,c); return r; }
static int ecb(fatvol*v,dent*d,void*a){ if(strcmp(d->name,".")&&strcmp(d->name,"..")){ *(int*)a=1; return 1; } return 0; }
int fat_remove(fatvol*v,const char*p){ dent d; u32 par; int root; int r=lookup(v,p,&d,&par,&root); if(r)return r; if(root)return VE_INVAL; if(d.e[11]&1)return VE_DENIED; if(d.e[11]&0x10){ int any=0; u32 c=ecl(d.e); r=walk(v,c,ecb,&any); if(r<0)return r; if(any)return VE_NOTEMPTY; } r=del_ent(v,&d); if(r)return r; v->d.fl(); u32 c=ecl(d.e); if(c)cfree(v,c); return 0; }
int fat_rename(fatvol*v,const char*a,const char*b){ dent d; u32 par; int root; int r=lookup(v,a,&d,&par,&root); if(r)return r; if(root)return VE_INVAL; size_t al=strlen(a); if(!memcmp(a,b,al)&&strlen(b)>=al&&(b[al]=='/'||!b[al]))return VE_INVAL; u32 dir; const char*n; int l; r=spl(v,b,&dir,&n,&l); if(r)return r; char nm[VFS_NAME+1]; memcpy(nm,n,l); nm[l]=0; fnd f; f.n=nm;f.l=l;f.hit=0; r=walk(v,dir,fcb,&f); if(r<0)return r; if(f.hit&&!(f.r.sec==d.sec&&f.r.off==d.off))return VE_EXIST; r=add(v,dir,nm,l,d.e[11],ecl(d.e),R32(d.e,28),0,d.e); if(r)return r; f.n=0; dent again; u32 pr; r=lookup(v,a,&again,&pr,&root); if(r)return r; r=del_ent(v,&again); if(r)return r; if((d.e[11]&0x10)&&dir!=par){ static u8 s[512]; u32 c=ecl(d.e); if(cvalid(v,c)&&!rs(v,c2s(v,c),s)&&s[32]=='.'&&s[33]=='.'){ u32 pc=dir==v->root?0:dir; W16(s+32,20,pc>>16); W16(s+32,26,pc&0xFFFF); ws(v,c2s(v,c),s); } } v->d.fl(); return 0; }
